class Solution:
    def nextBiggerFor(self, picks: List[int], row: List[int]) -> List[int]:
        out = []
        for p in picks:
            ans = -1
            for v in row[row.index(p) + 1:]:
                if v > p:
                    ans = v
                    break
            out.append(ans)
        return out

