function nextBiggerFor(picks: number[], row: number[]): number[] {
  const next = new Map<number, number>();
  const stack: number[] = [];
  for (const x of row) {
    while (stack.length && stack[stack.length - 1] < x) next.set(stack.pop()!, x);
    stack.push(x);
  }
  return picks.map(p => next.get(p) ?? -1);
}

